<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\TrustedClient\Domain\ValueObject\Accessor\TrustedClientTlsClientAuthSubjectDnAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the TrustedClientTlsClientAuthSubjectDnAccessor trait.
 *
 * Covers null default, string/VO assignment via withTlsClientAuthSubjectDn,
 * getTlsClientAuthSubjectDn/tlsClientAuthSubjectDn accessors, and isTlsClientAuthSubjectDnChanged with/without original.
 */
class TrustedClientTlsClientAuthSubjectDnAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withTlsClientAuthSubjectDn creates a new instance with the TlsClientAuthSubjectDn set
     * from a string value, and getTlsClientAuthSubjectDn returns the primitive string.
     */
    public function testWithTlsClientAuthSubjectDnFromString(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTlsClientAuthSubjectDnAccessorUnitTest();

        // Act
        $result = $holder->withTlsClientAuthSubjectDn('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getTlsClientAuthSubjectDn());
    }
    /**
     * Asserts that withtlsClientAuthSubjectDn has access to the value object
     * from a string value, and getTlsClientAuthSubjectDn returns the primitive string.
     */
    public function testWithTlsClientAuthSubjectDnFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTlsClientAuthSubjectDnAccessorUnitTest();

        // Act
        $result = $holder->withTlsClientAuthSubjectDn('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->tlsClientAuthSubjectDn()->value());
    }
    public function testChangedTlsClientAuthSubjectDn(): void
    {
        // Arrange
        $holder = new ImplWithTrustedClientTlsClientAuthSubjectDnAccessorUnitTest();
        $original = $holder->withTlsClientAuthSubjectDn('one');
        $same = $holder->withTlsClientAuthSubjectDn('one');
        $modified = $holder->withTlsClientAuthSubjectDn('other');

        // Act
        $unchanged = $holder->isTlsClientAuthSubjectDnChanged();
        $withSame = $original->isTlsClientAuthSubjectDnChanged($same);
        $withDiferent = $original->isTlsClientAuthSubjectDnChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithTrustedClientTlsClientAuthSubjectDnAccessorUnitTest
{
    use TrustedClientTlsClientAuthSubjectDnAccessor;
}
